param([string]$BaseUrl='http://127.0.0.1:8080',[ValidateRange(5,100)][int]$Samples=20)
$ErrorActionPreference='Stop';$root=Resolve-Path(Join-Path $PSScriptRoot '..\..');Set-Location $root;$cfg=@{};Get-Content .env|Where-Object{$_-match'^\s*([^#=\s]+)=(.*)$'}|ForEach-Object{$cfg[$matches[1]]=$matches[2].Trim().Trim('"').Trim("'")};$login=Invoke-RestMethod -Method Post "$BaseUrl/api/v1/auth/token" -ContentType application/json -Body(@{username=$cfg.PLATFORM_BOOTSTRAP_USER;password=$cfg.PLATFORM_BOOTSTRAP_PASSWORD}|ConvertTo-Json);$h=@{Authorization="Bearer $($login.access_token)"};$tenant=$cfg.PLATFORM_BOOTSTRAP_TENANT_ID
function Api($path,$body){(Invoke-RestMethod -Method Post "$BaseUrl$path" -Headers $h -ContentType application/json -Body($body|ConvertTo-Json -Depth 20 -Compress)).data};function P([double[]]$v,[double]$p){$s=@($v|Sort-Object);[Math]::Round($s[[Math]::Min($s.Count-1,[Math]::Ceiling($p*$s.Count)-1)],2)};function Summary([double[]]$v){[ordered]@{count=$v.Count;p50Ms=P $v .5;p95Ms=P $v .95;p99Ms=P $v .99;maxMs=[Math]::Round(($v|Measure-Object -Maximum).Maximum,2)}}
$null=Api '/internal/v1/detection-starter-fixtures:seed' @{};$null=Api '/internal/v1/correlation-production-pack:seed' @{};$d=@();$c=@();$findingIds=@();$correlationIds=@();for($i=0;$i-lt$Samples;$i++){$endpoint=[guid]::NewGuid();$at=[DateTimeOffset]::UtcNow;$eventId=[guid]::NewGuid();$event=@{eventId=$eventId;tenantId=$tenant;domain='Process';eventTime=$at.ToString('o');endpointId=$endpoint;processEntityId="s29-$i";entityId="s29-$i";fields=@{path="C:\Sprint12Fixtures\profile-a-$i.exe";processName="profile-a-$i.exe";endpointId=$endpoint.ToString()};evidenceReference="postgresql://platform/sprint29_latency/$eventId";late=$false;incomplete=$false;missingTelemetry=@();quality=@('complete')};$sw=[Diagnostics.Stopwatch]::StartNew();$x=Api '/internal/v1/detection-events:evaluate' @{event=$event;productionFindings=$true};$sw.Stop();if(-not$x.finding){throw 'Controlled detection finding was not produced.'};$d+=$sw.Elapsed.TotalMilliseconds;$findingIds+=$x.finding.findingId
 $fileId=[guid]::NewGuid();$file=@{observationId=$fileId;tenantId=$tenant;kind='Event';domain='File';eventTime=$at.ToString('o');ingestedAt=$at.AddMilliseconds(1).ToString('o');endpointId=$endpoint;processEntityId="s29-c-$i";parentProcessEntityId=$null;entityId="s29-file-$i";detectionFindingId=$null;detectionId=$null;fields=@{endpointId=$endpoint.ToString();operation='Created';extension='.exe'};evidenceReference="postgresql://platform/sprint29_latency/$fileId";late=$false;incomplete=$false;missingTelemetry=@();quality=@('complete');confidence=10};$procId=[guid]::NewGuid();$proc=$file.Clone();$proc.observationId=$procId;$proc.domain='Process';$proc.eventTime=$at.AddMilliseconds(2).ToString('o');$proc.ingestedAt=$at.AddMilliseconds(3).ToString('o');$proc.entityId="s29-process-$i";$proc.fields=@{endpointId=$endpoint.ToString();path="C:\Users\Public\s29-$i.exe"};$null=Api '/internal/v1/correlation-observations:evaluate' @{observation=$file;productionFindings=$true;mode='Live'};$sw.Restart();$y=Api '/internal/v1/correlation-observations:evaluate' @{observation=$proc;productionFindings=$true;mode='Live'};$sw.Stop();if(-not$y.matched){throw 'Controlled correlated finding was not produced.'};$c+=$sw.Elapsed.TotalMilliseconds;$correlationIds+=$y.finding.correlatedFindingId}
$deadline=(Get-Date).AddSeconds(120);do{$q=(docker exec deployment-postgres-1 psql -U platform -d platform -Atc "select count(*) filter(where published_at is null and failed_at is null)||'|'||count(*) filter(where failed_at is not null) from platform.outbox;").Trim();if($q-eq'0|0'){break};Start-Sleep 2}while((Get-Date)-lt$deadline)
$result=[ordered]@{schemaVersion='sprint29-engine-latency.v1';executedAt=[DateTimeOffset]::UtcNow.ToString('o');measurement='HTTP receipt of final canonical controlled evidence through authoritative transaction and finding response';detection=Summary $d;correlation=Summary $c;uniqueDetectionFindings=@($findingIds|Select-Object -Unique).Count;uniqueCorrelatedFindings=@($correlationIds|Select-Object -Unique).Count;outbox=$q;duplicateFindings=($Samples-@($findingIds|Select-Object -Unique).Count)+($Samples-@($correlationIds|Select-Object -Unique).Count);passed=@($findingIds|Select-Object -Unique).Count-eq$Samples-and@($correlationIds|Select-Object -Unique).Count-eq$Samples-and$q-eq'0|0'};$result|ConvertTo-Json -Depth 10|Set-Content artifacts/sprint29-engine-latency.json -Encoding utf8;$result|ConvertTo-Json -Depth 10;if(-not$result.passed){throw 'Sprint 29 engine latency qualification failed.'}
